const base = { a: 1, b: 2, c: 3 };
const extended = { ...base, d: 4, b: 99 }; // b nadpisany PO spreadzie

console.log(extended); // { a: 1, b: 99, c: 3, d: 4 }
// b: 99 WYGRYWA, bo wystapilo PO ...base w kolejnosci zapisu

const original = { name: "Jan", scores: [10, 20] };
const copy = { ...original };

copy.name = "Marek";   // OK - nie wplywa na oryginal (proste wartosci)
copy.scores.push(30);  // UWAGA - wplywa NA OBA! scores to TA SAMA referencja

console.log(original.name);   // "Jan" - niezmienione
console.log(original.scores); // [10, 20, 30] - ZMIENIONE mimo modyfikacji 'copy'!

const state = { user: null, loading: false, error: null };

const loadingState = { ...state, loading: true };
const successState = { ...state, user: { name: "Anna" }, loading: false };

console.log(state.loading); // false - oryginalny stan NIENARUSZONY
console.log(loadingState);  // { user: null, loading: true, error: null }
console.log(successState);  // { user: { name: 'Anna' }, loading: false, error: null }

const state = { loading: false, user: null };

const loadingState = { loading: true, ...state }; // BLEDNIE: spread PO nadpisaniu
console.log(loadingState); // { loading: false, user: null } - loading NIE ZMIENIONE!

const state = { loading: false, user: null };

const loadingState = { ...state, loading: true }; // POPRAWNIE: spread PRZED nadpisaniem
console.log(loadingState); // { loading: true, user: null }

